WITH unpacked AS (SELECT id, effective_from, tier_limits, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT *, AVG(entry_price) OVER (ORDER BY effective_from, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) entry_price_avg_5_prior, AVG(entry_price) OVER (ORDER BY effective_from, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) entry_price_avg_6 FROM unpacked;
